create extension if not exists pgcrypto;
do $$ begin create type public.imcs_role as enum ('SUPER_ADMIN','DIRECTOR','COMMISSIONER','EXECUTIVE','DEPARTMENT_HEAD','MANAGER','STAFF','AUDITOR'); exception when duplicate_object then null; end $$;
do $$ begin create type public.project_status as enum ('PIPELINE','PLANNING','ACTIVE','ON_HOLD','COMPLETED','CANCELLED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.risk_level as enum ('LOW','MEDIUM','HIGH','CRITICAL'); exception when duplicate_object then null; end $$;
do $$ begin create type public.approval_status as enum ('DRAFT','PENDING','APPROVED','REJECTED','CANCELLED'); exception when duplicate_object then null; end $$;
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),parent_id uuid references public.organizations(id),code text unique not null,name text not null,organization_type text not null default 'BUSINESS_UNIT',active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,organization_id uuid references public.organizations(id),full_name text,role public.imcs_role not null default 'STAFF',active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.land_assets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),code text not null,name text not null,location text,area_m2 numeric(18,2),acquisition_value numeric(20,2),current_value numeric(20,2),legal_status text,zoning text,encumbrance text,development_potential text,created_at timestamptz not null default now(),unique(organization_id,code));
create table if not exists public.land_documents(id uuid primary key default gen_random_uuid(),land_asset_id uuid not null references public.land_assets(id) on delete cascade,document_type text not null,document_number text,issue_date date,expiry_date date,file_path text,verified_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.property_projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),code text not null,name text not null,status public.project_status not null default 'PIPELINE',land_asset_id uuid references public.land_assets(id),gdv numeric(20,2),target_margin_pct numeric(9,4),start_date date,target_end_date date,created_at timestamptz not null default now(),unique(organization_id,code));
create table if not exists public.project_costs(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.property_projects(id) on delete cascade,cost_category text not null,budget numeric(20,2) not null default 0,committed numeric(20,2) not null default 0,actual numeric(20,2) not null default 0,created_at timestamptz not null default now());
create table if not exists public.project_risks(id uuid primary key default gen_random_uuid(),project_id uuid references public.property_projects(id) on delete cascade,title text not null,description text,level public.risk_level not null default 'MEDIUM',probability numeric(9,4),impact numeric(20,2),mitigation text,owner_id uuid references public.profiles(id),due_date date,closed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.properties(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid references public.property_projects(id),code text not null,name text not null,property_type text,status text,area_m2 numeric(18,2),asking_value numeric(20,2),created_at timestamptz not null default now(),unique(organization_id,code));
create table if not exists public.investment_cases(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid references public.property_projects(id),name text not null,assumptions jsonb not null default '{}',irr numeric(12,6),npv numeric(20,2),roi numeric(12,6),approved boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.budgets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),fiscal_year int not null,name text not null,amount numeric(20,2) not null default 0,status public.approval_status not null default 'DRAFT',created_at timestamptz not null default now());
create table if not exists public.financial_transactions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid references public.property_projects(id),transaction_date date not null,account_code text not null,description text,debit numeric(20,2) not null default 0,credit numeric(20,2) not null default 0,reference_no text,created_at timestamptz not null default now());
create table if not exists public.contracts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),contract_no text not null,title text not null,counterparty text,start_date date,end_date date,value numeric(20,2),status text,document_path text,created_at timestamptz not null default now(),unique(organization_id,contract_no));
create table if not exists public.approvals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),entity_type text not null,entity_id uuid not null,requested_by uuid references public.profiles(id),approver_id uuid references public.profiles(id),status public.approval_status not null default 'PENDING',requested_at timestamptz not null default now(),decided_at timestamptz,decision_note text);
create table if not exists public.audit_logs(id bigint generated always as identity primary key,organization_id uuid references public.organizations(id),actor_id uuid references public.profiles(id),action text not null,entity_type text,entity_id uuid,before_data jsonb,after_data jsonb,created_at timestamptz not null default now());
create table if not exists public.kpi_catalog(code text primary key,name text not null,unit text,description text,active boolean not null default true);
create table if not exists public.kpi_actuals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),kpi_code text not null references public.kpi_catalog(code),period_date date not null,value_numeric numeric(24,4),source text,created_at timestamptz not null default now(),unique(organization_id,kpi_code,period_date));
create table if not exists public.management_alerts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),severity public.risk_level not null,rule_code text not null,title text not null,message text not null,entity_type text,entity_id uuid,status text not null default 'OPEN',created_at timestamptz not null default now(),resolved_at timestamptz);
create schema if not exists legacy_staging;
create table if not exists legacy_staging.import_batches(id uuid primary key default gen_random_uuid(),source_name text not null,source_hash text,extracted_at timestamptz,status text not null default 'EXTRACTED',notes text,created_at timestamptz not null default now());
create table if not exists legacy_staging.raw_records(id bigint generated always as identity primary key,batch_id uuid not null references legacy_staging.import_batches(id) on delete cascade,source_table text not null,source_row_number bigint,payload jsonb not null,row_hash text,validation_status text not null default 'PENDING',validation_errors jsonb,created_at timestamptz not null default now());
insert into public.organizations(code,name,organization_type) values('ADTRANS','PT ADTRANS RENTCAR INDONESIA','PARENT') on conflict(code) do nothing;
insert into public.organizations(parent_id,code,name,organization_type) select id,'REALINDO','ADTrans RealIndo','BUSINESS_UNIT' from public.organizations where code='ADTRANS' on conflict(code) do nothing;
insert into public.kpi_catalog(code,name,unit,description) values('LAND_BANK_AREA','Land Bank Area','m2','Total controlled land area'),('LAND_VALUE','Land Value','IDR','Current land value'),('PROJECT_GDV','Project GDV','IDR','Gross development value'),('PROJECT_MARGIN','Project Margin','%','Project margin'),('CASH_POSITION','Cash Position','IDR','Cash position'),('RECEIVABLES','Receivables','IDR','Outstanding receivables'),('RISK_EXPOSURE','Risk Exposure','IDR','Financial exposure from material risks') on conflict(code) do nothing;
